def tri_selection(liste):
    resultat = list(liste)
    for i in range(len(resultat)):
        mini = i
        for j in range(i + 1, len(resultat)):
            if resultat[j] < resultat[mini]:
                mini = j
        resultat[i], resultat[mini] = resultat[mini], resultat[i]
    return resultat

def tri_insertion(liste):
    resultat = list(liste)
    for i in range(1, len(resultat)):
        valeur = resultat[i]
        j = i - 1
        while j >= 0 and resultat[j] > valeur:
            resultat[j + 1] = resultat[j]
            j -= 1
        resultat[j + 1] = valeur
    return resultat

